// CoverageStats carries the gate WITH its method, never as a bare number.
//
// §8.19.1: the denominator is `entity_kind='listed'`, which the resolver assigns
// BY DEFAULT to anything it cannot otherwise explain. A percentage that travels
// 30.66% -> 49.89% -> ~80% with the numerator frozen is measuring our ability to
// EXPLAIN failures, not to RESOLVE them. Both halves are reported separately so
// nobody can quote the ratio without them.
type CoverageStats struct {
	state protoimpl.MessageState `protogen:"open.v1"`
	// Item-1 candidates resolved to an ASX code. The numerator. Only this moves
	// when a real new link is made.
	Resolved int32 `protobuf:"varint,1,opt,name=resolved,proto3" json:"resolved,omitempty"`
	// Item-1 candidates carrying entity_kind='listed'. The denominator, and a
	// DEFAULT bucket rather than a measured claim.
	ListedCandidates int32 `protobuf:"varint,2,opt,name=listed_candidates,json=listedCandidates,proto3" json:"listed_candidates,omitempty"`
	// resolved / listed_candidates, as a percentage.
	GatePercent float64 `protobuf:"fixed64,3,opt,name=gate_percent,json=gatePercent,proto3" json:"gate_percent,omitempty"`
	// Undecided names still in the queue, and the rows behind them.
	BacklogCandidates int32 `protobuf:"varint,4,opt,name=backlog_candidates,json=backlogCandidates,proto3" json:"backlog_candidates,omitempty"`
	BacklogRows       int32 `protobuf:"varint,5,opt,name=backlog_rows,json=backlogRows,proto3" json:"backlog_rows,omitempty"`
	// Item-1 candidates a human has explicitly classified out of the denominator.
	// The honest half of any movement in gate_percent.
	ClassifiedOut int32 `protobuf:"varint,6,opt,name=classified_out,json=classifiedOut,proto3" json:"classified_out,omitempty"`
	// How the figure was computed, carried with it so it cannot be quoted bare.
	Method        string `protobuf:"bytes,7,opt,name=method,proto3" json:"method,omitempty"`
	unknownFields protoimpl.UnknownFields
	sizeCache     protoimpl.SizeCache
}

